<script lang="ts">
  import { onMount } from 'svelte';
  let connected=false, showAll=true, lines=['$ hii console --stream matrix --agents','connecting to local context stream...'];
  let capabilities:any[]=[]; let jobs:any[]=[]; let prompt='Observe HII, AII, Termite, Codex, Claude, Ollama, and local dev server activity. Report stuck agents, blocked permission prompts, failed builds, and next actions.'; let preset='observer'; let name='hii-observer'; let spawning=false; let error=''; let terminal:HTMLPreElement;
  onMount(()=>{Promise.all([fetch('/api/capabilities').then(r=>r.json()),fetch('/api/capabilities/jobs').then(r=>r.json())]).then(([a,b])=>{capabilities=a.capabilities||[];jobs=b.jobs||[]});const source=new EventSource('/api/terminal/stream');source.onopen=()=>connected=true;source.addEventListener('snapshot',(event)=>{const snap=JSON.parse((event as MessageEvent).data);lines=[...lines,'',`--- ${new Date(snap.capturedAt).toLocaleTimeString()} ${snap.host} processes:${snap.processCount} agents:${snap.agentCount} ---`,...(snap.agents||[]).map((a:any)=>`[agent] ${a.name||a.id||a.pid} ${a.state||a.status||'unknown'}`),...(snap.processes||[]).filter((p:any)=>showAll||p.agent).map((p:any)=>`${p.agent?'[agent-process]':'[process]'} ${p.raw}`)].slice(-1800);setTimeout(()=>terminal?.scrollTo({top:terminal.scrollHeight}),0)});source.onerror=()=>connected=false;return()=>source.close()});
  async function spawn(){spawning=true;error='';const response=await fetch('/api/terminal/sessions',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({preset,prompt,name})});const body=await response.json();if(response.ok)lines=[...lines,`--- spawned ${body.run?.name||name} ---`,body.run?.output||'spawn accepted'];else error=body.error||'Failed to spawn agent.';spawning=false;}
</script>
<div class="hii-page"><section class="hii-page-header"><p class="hii-kicker">HII console</p><h1 class="hii-page-title">Matrix view for system and agent work.</h1><p class="hii-page-copy">A local-only power layer for watching agent sessions, HII jobs, approvals, and proof receipts as one transcript.</p></section><section class="grid gap-5 pt-6 lg:grid-cols-[minmax(18rem,22rem)_1fr]"><aside class="space-y-5"><div class="hii-card"><div class="flex justify-between"><h2 class="font-semibold">Stream</h2><span class="border px-2 py-1 text-xs uppercase">{connected?'live':'offline'}</span></div><label class="mt-4 flex gap-2 text-sm"><input type="checkbox" bind:checked={showAll}/> Show all system processes</label><button class="hii-secondary-action mt-4 w-full" on:click={()=>lines=['$ hii console --clear']}>Clear console</button></div><div class="hii-card"><h2 class="font-semibold">Capability Registry</h2>{#each capabilities as capability}<div class="mt-3 border-t pt-3"><div class="flex justify-between"><strong>{capability.name}</strong><span class="font-mono text-xs">{capability.status}</span></div><p class="font-mono text-xs text-neutral-500">{capability.id}</p></div>{/each}</div></aside><div><div class="hii-terminal-frame"><div class="flex items-center justify-between border-b border-white/20 px-4 py-3 font-mono text-xs"><span>HII / LOCAL MATRIX</span><span>{connected?'CONNECTED':'RECONNECTING'}</span></div><pre bind:this={terminal} class="h-[560px] overflow-auto whitespace-pre-wrap p-4 font-mono text-[11px] leading-5">{lines.join('\n')}</pre></div><div class="hii-card mt-5"><h2 class="font-semibold">Spawn bounded agent</h2><div class="mt-3 grid gap-3"><input class="hii-field px-3 py-2" bind:value={name}/><select class="hii-select px-3 py-2" bind:value={preset}><option>observer</option><option>shipper</option></select><textarea class="hii-textarea px-3 py-2" rows="5" bind:value={prompt}></textarea><button class="hii-command-button" disabled={spawning} on:click={spawn}>{spawning?'Starting…':'Start agent'}</button>{#if error}<p class="text-red-600">{error}</p>{/if}</div></div></div></section></div>
